<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, defectNames, imageUrl, shortId } from '../api'
import type { Asset, Task } from '../types'
const props = defineProps<{ asset: Asset; assets: Asset[] }>(), emit = defineEmits<{ close: []; saved: [] }>()
const label = ref(props.asset.label || ''), quality = ref(props.asset.quality || ''), reason = ref(props.asset.rejectionReason || ''), busy = ref(false), task = ref<Task>()
const comparisons = computed(() => [{ title: '原始参考图', id: props.asset.rootSourceId }, ...(props.asset.parentPoseId ? [{ title: '当前姿势底图', id: props.asset.parentPoseId }] : []), { title: props.asset.role === 'POSE' ? '待审核底图' : '生成结果', id: props.asset.id }])
// Intended defect is shown as context only; reviewer must explicitly choose the verified label.
onMounted(async () => { if (props.asset.taskId) task.value = await api<Task>(`/tasks/${props.asset.taskId}`) })
async function review(status: string) { busy.value = true; try { await api(`/assets/${props.asset.id}/review`, 'PUT', { status, label: label.value, quality: quality.value, reason: reason.value }); emit('saved') } finally { busy.value = false } }
</script>
<template>
  <el-dialog :model-value="true" :title="`人工审核 · ${shortId(asset.id)}`" width="min(1280px, 96vw)" @close="emit('close')"><el-alert v-if="asset.sourceType === 'TEST'" title="测试图片：仅验证工作流，不代表 AI 生成结果，不能导出为训练样本。" type="warning" :closable="false" /><div class="compare-grid"><figure v-for="(item,index) in comparisons" :key="index"><figcaption>{{ item.title }} <code>{{ shortId(item.id) }}</code></figcaption><el-image :src="imageUrl(item.id)" :preview-src-list="comparisons.map(c => imageUrl(c.id))" :initial-index="index" fit="contain" preview-teleported /></figure></div><div class="review-note"><b>检查清单</b><span>指定字符是否正确 · 其他字符是否移位或乱码 · 喷码是否过黑过粗 · 是否继承旧缺陷 · 是否混入额外缺陷 · 产品比例和姿势是否正确</span></div><p v-if="task" class="muted">生成日期：{{ task.params.baseDate }}；预期效果：{{ task.params.defect ? defectNames[task.params.defect.type] : '正常日期底图' }}；预期字符位置：{{ task.params.defect?.positions.join('、') || '无' }}。下方为独立人工确认标签。</p><el-form label-position="top"><div class="form-row"><el-form-item label="人工确认缺陷标签（通过时必填）"><el-select v-model="label" filterable allow-create default-first-option placeholder="人工确认，支持自定义标签"><el-option v-for="(name,key) in (asset.role === 'POSE' ? { normal: '正常底图' } : defectNames)" :key="key" :value="key" :label="name" /></el-select></el-form-item><el-form-item label="产品质量判定（与审核状态独立）"><el-radio-group v-model="quality"><el-radio value="OK">OK · 正常产品</el-radio><el-radio value="NG" :disabled="asset.role === 'POSE'">NG · 缺陷产品</el-radio></el-radio-group></el-form-item></div><el-form-item label="不通过原因 / 审核备注"><el-input v-model="reason" type="textarea" :rows="2" maxlength="1000" /></el-form-item></el-form><template #footer><span class="muted footer-note">缺码图符合制作要求时，可审核通过并标记 NG。</span><el-button :loading="busy" @click="review('PENDING')">暂存待审核</el-button><el-button type="danger" plain :loading="busy" @click="review('REJECTED')">不通过</el-button><el-button type="primary" :loading="busy" @click="review('APPROVED')">通过审核</el-button></template></el-dialog>
</template>
